parameters.jsCode:
let array = $('Edit Fields2').first().json.turnos;
let data = $('Code1').first().json;
array.push(data);

return $input.all()

const result = $('GetTurnos').first();
const entitydata = result?.json?.result?.entitydata;

if (!entitydata) {
  // no existe entitydata → corto el flujo
  return [];
}

if (entitydata.length === 0) {
  // existe pero está vacío → corto el flujo
  return [];
}

const now = new Date();
const todayCode = now.getFullYear() * 10000 + (now.getMonth() + 1) * 100 + now.getDate();

const filtered = entitydata.filter(item => {
  if (!item.scheduled_date_code) return false;
  return item.scheduled_date_code >= todayCode;
});

// si después de filtrar también queda vacío → corto el flujo
if (filtered.length === 0) {
  return [];
}

// devuelvo items válidos
return filtered.map(f => ({ json: f }));

const datos = $input.all();

// 🔹 Filtramos solo ítems válidos con estructura completa
const datosValidos = datos.filter(item => 
  item?.json &&
  item.json.date &&
  item.json.hour &&
  item.json.hour.code &&
  (item.json.workshop_appointment_guid === null || item.json.workshop_appointment_guid === undefined)
);

const agrupadosPorFecha = {};

// 🔹 Agrupar por fecha
datosValidos.forEach(item => {
  const fecha = item.json.date;
  if (!agrupadosPorFecha[fecha]) {
    agrupadosPorFecha[fecha] = [];
  }
  agrupadosPorFecha[fecha].push(item);
});

const resultadoFinal = [];
const fechasDisponibles = Object.keys(agrupadosPorFecha);

// 🔹 Un turno aleatorio por cada día disponible
fechasDisponibles.forEach(fecha => {
  const turnosDelDia = agrupadosPorFecha[fecha];
  const randomIndex = Math.floor(Math.random() * turnosDelDia.length);
  resultadoFinal.push(turnosDelDia[randomIndex]);
});

// 🔹 Completar hasta 4 turnos, sin duplicados
while (resultadoFinal.length < 4 && fechasDisponibles.length > 0) {
  const fechaAleatoria = fechasDisponibles[Math.floor(Math.random() * fechasDisponibles.length)];
  const turnosDelDia = agrupadosPorFecha[fechaAleatoria];

  const turnosDisponibles = turnosDelDia.filter(turno => {
    return (
      turno?.json?.hour?.code &&
      !resultadoFinal.some(t => 
        t.json.date === turno.json.date && 
        t.json.hour.code === turno.json.hour.code
      )
    );
  });

  if (turnosDisponibles.length > 0) {
    const randomIndex = Math.floor(Math.random() * turnosDisponibles.length);
    resultadoFinal.push(turnosDisponibles[randomIndex]);
  } else {
    break;
  }
}

return resultadoFinal;

// Obtener todos los items del input
const data = $('GetModelos').all();
const data2 = $('GetModelos2').all()
// La data real está en data[0].json.result.entitydata
const entitydata = data[0].json?.result?.entitydata || [];
const entitydata2 = data2[0].json?.result?.entitydata || [];

const listaUnificada = entitydata.concat(entitydata2)

return listaUnificada.map(r => ({ json: r }));

